import * as zlib from 'node:zlib';

function report(label: string, fn: () => any): void {
  try {
    const r: any = fn();
    console.log(label, 'OK', r.length);
  } catch (e: any) {
    console.log(label, e.name, e.code, e.message);
  }
}

function main(): void {
  report('gzip number', () => zlib.gzipSync(5 as any));
  report('gzip object', () => zlib.gzipSync({ a: 1 } as any));
  report('gunzip null', () => zlib.gunzipSync(null as any));
  report('inflate undefined', () => zlib.inflateSync(undefined as any));
  report('deflate array', () => zlib.deflateSync([1, 2, 3] as any));
  report('unzip boolean', () => zlib.unzipSync(true as any));
  report('brotli string-like number', () => zlib.brotliCompressSync(7 as any));
  report('options before buffer', () => zlib.gzipSync(5 as any, { level: 99 }));
  report('level string', () => zlib.deflateSync(Buffer.from('abc'), { level: 'x' } as any));
  report('level range', () => zlib.inflateRawSync(Buffer.from('abc'), { level: 99 }));
  report('brotli ignores level', () => zlib.brotliCompressSync(Buffer.from('hello'), { level: 99 } as any));
  report('DataView input', () => zlib.gzipSync(new DataView(new ArrayBuffer(4))));
  report('ArrayBuffer input', () => zlib.deflateSync(new ArrayBuffer(4)));
  const backing = new Uint8Array(32);
  backing.set(Buffer.from('hello thaw zlib'), 5);
  const view = new Uint8Array(backing.buffer, 5, 15);
  console.log('subview round trip', zlib.gunzipSync(zlib.gzipSync(view)).toString());
  const dv = new DataView(backing.buffer, 5, 15);
  console.log('dataview round trip', zlib.inflateSync(zlib.deflateSync(dv)).toString());
}
